"""Application version definition for xarrtools."""
import os

__version__ = "0.0.0-dev"

# 1. Build-time stamped file (generated by release builds for frozen binaries)
try:
    from core._version import __version__ as _stamped_version  # type: ignore[import-not-found]
    if _stamped_version:
        __version__ = str(_stamped_version)
except (ImportError, ModuleNotFoundError):
    pass

# 2. Runtime environment variable override (Docker containers, testing)
if os.environ.get("XARRTOOLS_VERSION"):
    __version__ = os.environ["XARRTOOLS_VERSION"]
